// DataPeerServiceServer is the server API for DataPeerService service.
// All implementations must embed UnimplementedDataPeerServiceServer
// for forward compatibility.
//
// DataPeerService is the data-plane half: everything that touches a slot's
// content — replica fetch and progress, migration fences, copy removal, and
// the per-slot gauges the controller reads off the nodes that hold the copies.
type DataPeerServiceServer interface {
	// MFetch is the multiplexed replica fetch: every slot this follower
	// copies from the serving leader is one item; the call long-polls when
	// everything is empty (wait_ms budget, server-held).
	MFetch(context.Context, *MFetchRequest) (*MFetchResponse, error)
	// ReplicaProgress reports follower LEOs in bulk after a productive round.
	ReplicaProgress(context.Context, *ReplicaProgressRequest) (*ReplicaProgressResponse, error)
	// Replicate pushes one leader-assigned record to the migration target
	// during the forwarding window (idempotent at seq).
	Replicate(context.Context, *ReplicateRequest) (*ReplicateResponse, error)
	// ReplicateAggregate streams one aggregate's records out of a slot, so a
	// generation migration can replay them into the slot the new segment routes
	// them to. The CALLER pulls (the destination asks the source); the cursor is
	// the aggregate version, which is what makes the replay resumable.
	ReplicateAggregate(*ReplicateAggregateRequest, grpc.ServerStreamingServer[ReplicateAggregateResponse]) error
	// SlotStreams lists the aggregates a slot holds, which is what a generation
	// migration needs before it can replay: it walks the source slot's streams and
	// asks the destination to pull each one.
	SlotStreams(context.Context, *SlotStreamsRequest) (*SlotStreamsResponse, error)
	// ReplayInto asks the DESTINATION to pull one aggregate out of a source slot
	// and land it in a local slot. The bytes flow peer-to-peer; the controller only
	// pairs the two ends.
	ReplayInto(context.Context, *ReplayIntoRequest) (*ReplayIntoResponse, error)
	// SlotLeo answers a single slot's log end offset (migration catch-up).
	SlotLeo(context.Context, *SlotLeoRequest) (*SlotLeoResponse, error)
	// FenceSlot is the migration commit fence: the source stops accepting new
	// appends for the slot (they block, they are never rejected), drains the
	// in-flight ones, pushes the frozen tail to the target and answers with the
	// frozen log end offset only once the target has confirmed it holds that
	// offset. The fence stays held until the leader move (or an abort) is
	// applied, and is force-released after a bound so a lost controller cannot
	// wedge the slot's writes.
	FenceSlot(context.Context, *FenceSlotRequest) (*FenceSlotResponse, error)
	// FreezeSlot closes a slot's write gate and keeps it closed until ThawSlot:
	// a generation migration freezes the whole source segment, replays the tails,
	// switches, and only then thaws (the slots are gone from the table by then).
	// It is NOT FenceSlot: that one freezes in order to hand leadership over and
	// waits for the demotion, which is a different contract.
	FreezeSlot(context.Context, *FreezeSlotRequest) (*FreezeSlotResponse, error)
	ThawSlot(context.Context, *ThawSlotRequest) (*ThawSlotResponse, error)
	// SlotLeader answers THIS node's local view of one slot: which node it
	// believes leads it and at which epoch. The migration source uses it to gate
	// the commit-fence release on the target having actually applied the leader
	// move — without it the source starts redirecting the moment IT applies the
	// move, and a client that then asks the not-yet-updated target is bounced
	// back to the source: an infinite MOVED/ASK ping-pong for the length of the
	// follower apply lag (clients with a small redirect budget fail).
	SlotLeader(context.Context, *SlotLeaderRequest) (*SlotLeaderResponse, error)
	// DropSlot discards this node's local copy of one slot and reopens it empty.
	// Used by the migration fence when a target's streams are inconsistent with
	// its LEO (DESIGN.md §1.1 rule 3): the increment that would repair it cannot
	// be shipped, because the seqs the missing versions need are already spent, so
	// the copy is rebuilt from the source instead. The caller owns the slot's
	// placement and must not be asking a node that serves it.
	DropSlot(context.Context, *DropSlotRequest) (*DropSlotResponse, error)
	// SlotLeos answers the durable LEO of many slots at once. The controller asks
	// it of every candidate before failing a node over: the failover must hand a
	// slot's leadership to a replica that HOLDS what was acknowledged, and only
	// the replicas themselves know their LEO (the slot table carries no offsets).
	// A slot this node does not hold reports 0.
	SlotLeos(context.Context, *SlotLeosRequest) (*SlotLeosResponse, error)
	// SlotSizes answers the on-disk size AND the seq ledger of many slots at
	// once, for the cluster storage gauges: the sums an operator watches count
	// each slot's LEADER copy (the copy the writes landed on), and only the
	// holder of a copy can report its bytes and its seq. A slot this node does
	// not hold answers 0 on both arrays.
	SlotSizes(context.Context, *SlotSizesRequest) (*SlotSizesResponse, error)
	mustEmbedUnimplementedDataPeerServiceServer()
}

